"""Dashboard read API — the Enhanced Monitoring Dashboard summary (Week 6, ADR 0022)."""

from __future__ import annotations

import uuid
from datetime import date
from typing import Annotated

from fastapi import APIRouter, Depends, Query
from sqlalchemy.orm import Session

from backend.app.api.v1._base import ApiModel
from backend.app.core.auth import get_current_user
from backend.app.core.roles import is_workspace_admin
from backend.app.db.models import User
from backend.app.db.session import get_db
from backend.app.services import dashboard_service as svc

router = APIRouter(tags=["dashboard"])

_WINDOW_DEFAULT = 7
_WINDOW_MAX = 90



@router.get(
    "/dashboard/summary",
    response_model=DashboardSummaryRead,
    summary="Dashboard summary — KPIs, run trend, per-suite performance",
)
def get_dashboard_summary(
    current_user: Annotated[User, Depends(get_current_user)],
    db: Annotated[Session, Depends(get_db)],
    window_days: Annotated[int, Query(ge=1, le=_WINDOW_MAX)] = _WINDOW_DEFAULT,
) -> DashboardSummaryRead:
    summary = svc.dashboard_summary(
        db,
        user_id=current_user.id,
        window_days=window_days,
        include_all=is_workspace_admin(current_user),
    )
    return DashboardSummaryRead(
        window_days=summary.window_days,
        kpis=KpisRead(
            health_score=summary.kpis.health_score,
            pass_rate=summary.kpis.pass_rate,
            total_runs=summary.kpis.total_runs,
            active_connections=summary.kpis.active_connections,
            avg_duration_ms=summary.kpis.avg_duration_ms,
            health_score_delta=summary.kpis.health_score_delta,
            pass_rate_delta=summary.kpis.pass_rate_delta,
            total_runs_delta_pct=summary.kpis.total_runs_delta_pct,
            avg_duration_delta_pct=summary.kpis.avg_duration_delta_pct,
        ),
        trend=[
            TrendPointRead(day=p.day, succeeded=p.succeeded, failed=p.failed) for p in summary.trend
        ],
        suite_performance=[
            SuitePerformanceRead(suite_id=s.suite_id, name=s.name, score=s.score, state=s.state)
            for s in summary.suite_performance
        ],
    )
          value={range}
          onChange={onRangeChange}
          options={WINDOW_PRESETS.map((r) => r.label)}
        />
      </Flex>

      {/* PANEL-level failure, deliberately an inline Alert not a PageError (#910):
          the page keeps rendering asset health and the tiles below, so a full-page
          error illustration wedged in the middle would misdescribe what failed. */}
      {state.status === 'error' && (
        <Alert type="error" showIcon title="Failed to load dashboard" description={state.error} />
      )}

      {/* Asset-level health leads the dashboard (ADR 0034 navigation inversion,
          #773) — assets are what users reason about; the KPI/trends below stay. */}
      <AssetHealthLead />

      {/* Five tiles: stacked on phones, 2-up on small screens, 3+2 at xl+. */}
      <Row gutter={[16, 16]}>
        <Col xs={24} sm={12} xl={8}>
          <MetricCard
            label="Data Integrity Score"
            value={pct(kpis?.health_score ?? null)}
            unit="%"
            icon={<SafetyCertificateOutlined />}
            progress={kpis?.health_score ?? null}
            delta={kpis?.health_score_delta}
            deltaUnit=" pts"
            loading={loading}
          />
        </Col>
        <Col xs={24} sm={12} xl={8}>
          <MetricCard
            label="Pass Rate"
            value={pct(kpis?.pass_rate ?? null)}
            unit="%"
            icon={<CheckCircleOutlined />}
            progress={kpis?.pass_rate ?? null}
            delta={kpis?.pass_rate_delta}
            deltaUnit=" pts"
            loading={loading}
          />
        </Col>
        <Col xs={24} sm={12} xl={8}>
          <MetricCard
            label="Total Runs"
            value={kpis ? kpis.total_runs : null}
            icon={<ThunderboltOutlined />}
            delta={kpis?.total_runs_delta_pct}
            footnote={`Last ${days === 1 ? '24h' : `${days} days`}`}
            loading={loading}
          />
        </Col>
        <Col xs={24} sm={12} xl={12}>
          <MetricCard
            label="Avg. Duration"
            value={kpis?.avg_duration_ms != null ? formatDurationMs(kpis.avg_duration_ms) : null}
            icon={<FieldTimeOutlined />}
            delta={kpis?.avg_duration_delta_pct}
            deltaGoodWhen="down"
            footnote="Per run, this window"
            loading={loading}
          />
        </Col>
        <Col xs={24} sm={12} xl={12}>
          <MetricCard
            label="Active Connections"
            value={kpis ? kpis.active_connections : null}
            unit="operational"
            icon={<ApiOutlined />}
            loading={loading}
          />
        </Col>
      </Row>

      <Row gutter={[16, 16]}>
