"""Set up DataQ's LOCAL stack against the local harness (not git-tracked).

Idempotent: every object is looked up by name first. Talks only to the real API, as
the real users, so it also exercises sign-in, roles and the connection tests.

    python dataq_setup/local_setup.py            # users, roles, connections, suites, bindings
    python dataq_setup/local_setup.py --run      # ...and start a run of every suite

Reads credentials from local/.env in-process. Nothing is printed.
"""

from __future__ import annotations

import argparse
import datetime as dt
import re
import sys
import time
from pathlib import Path
from typing import Any

import requests

API = "http://localhost:8000/api/v1"
MAILPIT = "http://localhost:8025/api/v1"
ENV = dict(
    line.split("=", 1)
    for line in (Path(__file__).resolve().parents[1] / "local" / ".env").read_text().splitlines()
    if "=" in line and not line.startswith("#")
)

USERS = {"admin@dataq.com": "admin", "user.01@dataq.com": "member", "guest@dataq.com": "viewer"}
NAMES = {"admin@dataq.com": "Local Admin", "user.01@dataq.com": "Local Member", "guest@dataq.com": "Local Guest"}


def sign_in(email: str) -> requests.Session:
    """Email-code sign-in, reading the code from the local mail catcher."""
    session = requests.Session()
    since = dt.datetime.now(dt.UTC)
    session.post(f"{API}/auth/otp/request", json={"email": email}).raise_for_status()
    for _ in range(30):
        time.sleep(1)
        found = requests.get(f"{MAILPIT}/search", params={"query": f"to:{email}", "limit": 1}).json()
        messages = found.get("messages", [])
        if not messages:
            continue
        created = dt.datetime.fromisoformat(messages[0]["Created"].replace("Z", "+00:00"))
        if created < since - dt.timedelta(seconds=2):
            continue
        text = requests.get(f"{MAILPIT}/message/{messages[0]['ID']}").json()["Text"]
        code = re.search(r"\b(\d{6})\b", text)
        if code:
            resp = session.post(f"{API}/auth/otp/verify", json={"email": email, "code": code.group(1)})
            resp.raise_for_status()
            return session
    raise SystemExit(f"no sign-in code arrived for {email}")


def ok(resp: requests.Response, what: str) -> Any:
    if resp.status_code >= 400:
        raise SystemExit(f"{what}: {resp.status_code} {resp.text[:400]}")
    return resp.json() if resp.content else None


def setup_users() -> dict[str, requests.Session]:
    sessions = {email: sign_in(email) for email in USERS}
    for email, session in sessions.items():
        ok(session.patch(f"{API}/me", json={"display_name": NAMES[email]}), f"name {email}")
    admin = sessions["admin@dataq.com"]
    for user in ok(admin.get(f"{API}/admin/users"), "list users"):
        wanted = USERS.get(user["email"])
        if wanted and user.get("role") != wanted and user["email"] != "admin@dataq.com":
            ok(admin.patch(f"{API}/admin/users/{user['id']}/role", json={"role": wanted}), f"role {user['email']}")
    for email, session in sessions.items():
        me = ok(session.get(f"{API}/me"), "me")
        print(f"user  {email:<22} role={me.get('role')} admin={me.get('is_workspace_admin')}")
    return sessions


def azurite_sas() -> str:
    from azure.storage.blob import ContainerSasPermissions, generate_container_sas

    return generate_container_sas(
        account_name=ENV["AZURITE_ACCOUNT_NAME"],
        container_name="landing",
        account_key=ENV["AZURITE_ACCOUNT_KEY"],
        permission=ContainerSasPermissions(read=True, list=True),
        expiry=dt.datetime.now(dt.UTC) + dt.timedelta(days=365),
    )


def connections() -> list[dict[str, Any]]:
    minio = {"region": "us-east-1", "endpoint_url": "http://minio:9000", "access_key_id": ENV["MINIO_ROOT_USER"]}
    return [
        {
            "name": "local-warehouse-postgres", "type": "postgres", "env": "dev",
            "config": {"host": "warehouse-postgres", "port": 5432, "database": "warehouse", "user": "dataq_reader", "schema": "retail", "sslmode": "disable"},
            "secret": ENV["WAREHOUSE_READER_PASSWORD"],
        },
        {
            "name": "local-mariadb", "type": "mysql", "env": "dev",
            "config": {"host": "mariadb", "port": 3306, "database": "retail", "user": "dataq_reader", "sslmode": "disable"},
            "secret": ENV["MARIADB_READER_PASSWORD"],
        },
        {
            "name": "local-trino", "type": "trino", "env": "dev",
            "config": {"host": "trino", "port": 8080, "catalog": "warehouse", "user": "dataq", "schema": "retail", "auth_type": "none", "sslmode": "disable"},
            "secret": None,
        },
        {
            "name": "local-minio-landing", "type": "s3", "env": "dev",
            "config": {"bucket": "landing", **minio},
            "secret": ENV["MINIO_ROOT_PASSWORD"],
        },
        {
            "name": "local-azurite-landing", "type": "adls", "env": "dev",
            "config": {"account_url": f"http://azurite:10000/{ENV['AZURITE_ACCOUNT_NAME']}", "container": "landing", "auth_type": "sas"},
            "secret": azurite_sas(),
        },
        {
            "name": "local-airflow", "type": "airflow", "env": "dev",
            "config": {"base_url": "http://airflow-webserver:8080", "auth_type": "basic", "username": "admin"},
            "secret": ENV["AIRFLOW_ADMIN_PASSWORD"],
        },
        {
            "name": "local-dbt", "type": "dbt", "env": "dev",
            "config": {"project_name": "dataq_lineage", "artifacts_uri": "s3://landing/dbt", "jobs": ["dataq_lineage"], **minio},
            "secret": ENV["MINIO_ROOT_PASSWORD"],
        },
    ]


def setup_connections(admin: requests.Session) -> dict[str, str]:
    existing = {c["name"]: c["id"] for c in ok(admin.get(f"{API}/connections"), "list connections")}
    ids: dict[str, str] = {}
    for spec in connections():
        if spec["name"] in existing:
            ids[spec["name"]] = existing[spec["name"]]
            print(f"conn  {spec['name']:<26} exists")
            continue
        body = {k: v for k, v in spec.items() if v is not None}
        resp = admin.post(f"{API}/connections", json=body)
        if resp.status_code >= 400:
            print(f"conn  {spec['name']:<26} REFUSED {resp.status_code}: {resp.json().get('error', {}).get('message', '')[:200]}")
            continue
        ids[spec["name"]] = resp.json()["id"]
        print(f"conn  {spec['name']:<26} created (tested on save)")
    return ids


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--run", action="store_true")
    parser.parse_args()
    sessions = setup_users()
    setup_connections(sessions["admin@dataq.com"])
    return 0


if __name__ == "__main__":
    sys.exit(main())
EOF
