import {
  ApiOutlined,
  CheckCircleOutlined,
  FieldTimeOutlined,
  SafetyCertificateOutlined,
  ThunderboltOutlined,
} from '@ant-design/icons';
import { Alert, Col, Flex, Row, Segmented, Typography } from 'antd';
import { useState } from 'react';

import { getDashboardSummary } from '../api/dashboard';
import { Page } from '../components/layout/Page';
import { AssetHealthLead } from '../components/dashboard/AssetHealthLead';
import { CoveragePanel } from '../components/dashboard/CoveragePanel';
import { WorkspaceDimensions } from '../components/dashboard/WorkspaceDimensions';
import { MetricCard } from '../components/dashboard/MetricCard';
import { formatDurationMs } from '../components/results/resultsFormat';
import { QualityTrends } from '../components/dashboard/QualityTrends';
import { RecentRuns } from '../components/dashboard/RecentRuns';
import { SuitePerformance } from '../components/dashboard/SuitePerformance';
import { WINDOW_PRESETS } from '../components/shared/windowPresets';
import { useAsyncData } from '../hooks/useAsyncData';

/** Enhanced Monitoring Dashboard (`/dashboard`, ADR 0022) — the post-login landing. */

/**
 * Range option label → trailing window in days for the summary query, shared with the Results date
 * filter (`WINDOW_PRESETS`, #349) so the two surfaces' 24h/7d/30d presets can't drift.
 */
type RangeLabel = (typeof WINDOW_PRESETS)[number]['label'];

function pct(value: number | null): string | null {
  return value === null ? null : `${value}`;
}

export function Dashboard() {
  const [range, setRange] = useState<RangeLabel>('Last 7 days');
