/** How often the checks list re-evaluates snooze expiry — a lapsed snooze must
 *  drop its badge/action without a manual refresh (minute granularity is plenty). */
const SNOOZE_TICK_MS = 60_000;

function ChecksList({
  suiteId,
  state,
  canEditChecks,
  onAdd,
  onEdit,
  onChanged,
}: {
  suiteId: string;
  state: AsyncState<Check[]>;
  /**
   * Edit capability — snooze/unsnooze AND re-baseline (#592) are edit-gated on the backend, so the
   * controls hide for view-only users (matching the sibling panels).
   */
  canEditChecks: boolean;
  onAdd: () => void;
  onEdit: (check: Check) => void;
  onChanged: () => void;
}) {
  const { message, modal } = App.useApp();
  const confirmDelete = useConfirmDelete();
  const [suggestOpen, setSuggestOpen] = useState(false);
  // Ticks so isSnoozed() re-evaluates while the page stays open: without it an
  // expired snooze keeps showing its badge/Unsnooze until the next refetch.
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), SNOOZE_TICK_MS);
    return () => clearInterval(id);
  }, []);

  // Bulk selection (edit-gated like every action it leads to). Ids, not rows, so a
      okType: 'danger',
      // Rejecting keeps the confirm open on failure, like the single delete.
      onOk: () =>
        runBulk(
          () => bulkDeleteChecks(suiteId, selectedIds),
          (n) => `${plural(n)} deleted`,
        ),
    });

  return (
    <Card
      size="small"
      title={`Checks (${checks.length})`}
      extra={
        <Flex gap={8}>
          {canEditChecks && (
            <Button size="small" onClick={() => setSuggestOpen(true)}>
              Suggest checks
            </Button>
          )}
          <Button type="primary" size="small" onClick={onAdd}>
            Add check
          </Button>
    const failed = results.filter((ok) => !ok).length;
    if (failed === 0) message.success(`All ${results.length} connections healthy`);
    else message.warning(`${failed} of ${results.length} connections unreachable`);
  };

  const actions: ConnectionActions = {
    // Editing is a dedicated page (create + edit pages replace the drawer, ADR 0022).
    onEdit: (connection) => navigate(`/connections/${connection.id}/edit`),
    onReauth: setReauthing,
    onChanged: reload,
    onTest: testOne,
    onClearHealth: clearHealth,
    // Server-derived, never a client-side decision (#743): every gated endpoint re-enforces with a
    // 403.
    canMutate,
    canAuthor,
  };

  return (
    <Page>
      <Flex justify="space-between" align="center" gap={12} wrap>
        <Typography.Title level={3} style={{ margin: 0 }}>
          Connections
        </Typography.Title>
        <Flex gap={8} align="center">
          {/* Read-only hint, not a scolding: a Member landing here needs to know
              the page is intentionally view-only for them, or the missing
              buttons read as a bug. Shown only once `/me` has resolved. */}
          {role !== null && !canMutate && (
            <Typography.Text type="secondary">
              {canAuthor
                ? 'Connections are managed by workspace admins'
                : 'Read-only — connections are managed by workspace admins'}
            </Typography.Text>
          )}
          {canAuthor && (
              the precondition that would enable it, and there isn't one. */}
